// ---------------------------------------------------------------------------
// AsciiString: BFME's header is one data pointer (8 bytes), and the copy ctor
// and dtor must be INLINE FORWARDERS to a StringBase<char> base that owns the
// out-of-line bodies -- retail copy ctor 0x00887B60, dtor 0x00887940.  This is
// inputs/reference/shims/stringinline/StringInline.h plus the out-of-line
// AsciiString::compare retail calls at ILT 0x000220C5.
// ---------------------------------------------------------------------------
template <typename T> struct StringInlineData
{
	int m_refCount;
	int m_length;
	T m_text[1];
};

template <typename T> class StringBase
{
	friend class AsciiString;

private:
	StringBase() : m_data( 0 ) {}
	StringBase( const StringBase<T> &other );
	~StringBase();

	StringInlineData<T> *m_data;
};

class AsciiString : private StringBase<char>
{
public:
	AsciiString() : StringBase<char>() {}
	AsciiString( const AsciiString &other ) : StringBase<char>( other ) {}
	~AsciiString() {}
	int compare( const AsciiString &other ) const;
};

inline Bool operator==( const AsciiString &a, const AsciiString &b )
{
	return a.compare( b ) == 0;
}

// ---------------------------------------------------------------------------
// Object: the DLINK pointer-to-member law.  The base that owns the team-member
// link sits at +4 and the base that introduces the virtual base (its own
// vbptr) sits at +0x68, so MSVC 7.1 encodes the link member's this-adjustment
// as 4 - 0x68 == -100 with vbindex 0 and emits
//   mov edx,[esi+0x68] / mov eax,[edx+0] / add eax,-100 / lea ecx,[eax+esi+0x68]
// exactly as retail does.  See inputs/reference/shims/objectdlink/ObjectDlinkPmf.h.
// ---------------------------------------------------------------------------
// ---------------------------------------------------------------------------
// ThingTemplate / Overridable: m_nextOverride at +0x04, m_name at +0x20.
// The override walk is the inline outer level plus the out-of-line recursive
// call at ILT 0x000022BB, which is why retail reads [eax+4] and branches
// before each of the two calls.
// ---------------------------------------------------------------------------
class Overridable
{
public:
	const Overridable *getFinalOverride( void ) const;

	void *m_vtable;									// +0x00
	Overridable *m_nextOverride;						// +0x04
};

class ThingTemplate : public Overridable
{
public:
	unsigned char m_beforeName[0x18];
	AsciiString m_name;								// +0x20
};

template <class TemplateType>
class BfmeOverride
{
public:
	const TemplateType *operator->() const
	{
		const TemplateType *value = m_overridable;
		if ( value != 0 && value->m_nextOverride != 0 )
			value = (const TemplateType *)value->m_nextOverride->getFinalOverride();
		return value;
	}

	const TemplateType *volatile m_overridable;
};

